scwin.__showLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err ? true : false;
}
scwin.__notShowMess = function() {
    return WebSquare.wUnit.getJq("#wq_uuid_3_dataLayer").find(".w2grid_fastScroll_layer").length == 0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 로그보기(ctrl+ 마우스우클릭)를 실행한다.
    //1. Execute the sample file and view the log (ctrl + right click).
    // verify step 1. 정상적인 로그가 보여진다.(이전에는 오류로그가 보여짐)
    //1. A normal log is shown.(Previously the error log is shown)
    WebSquare.wUnit.addCommand("assert", "scwin.__showLogNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 샘플파일을 실행 후 세로스크롤을 빠르게 아래까지 이동시킨다.
    //2. After running the sample file, move the vertical scroll to the bottom quickly.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_scrollY_div').scrollTop = 500");
    //Verify step 2. 정상적으로 버벅거림없이 빠르게 이동되어진다.(이전에는 그리드하단에 '화면이 갱신중입니다.'보여짐)
    //2. It can be moved quickly without hitting normally.(Previously, 'Screen is being updated' is displayed at the bottom of the grid.)
    WebSquare.wUnit.addCommand("assert", "scwin.__notShowMess()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
